import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int length = sc.nextInt();
        String inputStr = sc.next();
        int maxCount = -1;
        int currentCount = 0;
        int countNumbers = 0;
        boolean inParentheses = false;
        int alphaCount = 0;
        for (int index = 0; index < length; index++) {
            char ch = inputStr.charAt(index);
            if (!inParentheses) {
                if (isAlpha(ch)) {
                    currentCount++;
                }
                if (currentCount > 0 && (ch == '_' || ch == '(')) {
                    maxCount = Math.max(maxCount, currentCount);
                    currentCount = 0;
                }
            } else {
                if (isAlpha(ch)) {
                    alphaCount++;
                }
                if (ch == '_' || ch == ')') {
                    if (alphaCount > 0) {
                        countNumbers++;
                        alphaCount = 0;
                    }
                    if (ch == ')') {
                        inParentheses = false;
                    }
                }
            }
            if (ch == '(') {
                inParentheses = true;
            }
        }
        if (currentCount > 0) {
            maxCount = Math.max(maxCount, currentCount);
        }
        if (maxCount == -1) {
            System.out.print(0 + " ");
        } else {
            System.out.print(maxCount + " ");
        }
        System.out.println(countNumbers);
    }
    static boolean isAlpha(char c) {
        return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z');
    }
}
